import { useEffect, useMemo, useState } from 'react';
import type { ReactNode } from 'react';
import { ArrowUpRight, ChevronLeft, ChevronRight, CircleHelp, Search, ShieldCheck } from 'lucide-react';
import type { PageId, QualityKind } from '../domain/types';
import type { Group, Metrics, Scope } from '../domain/engine';
import { classifyContract, group, inWindow, isActiveLink, makeSeries, outstanding, priorityFor } from '../domain/engine';
import { dataset, companyById, establishmentById, cityById, greById, cnaeByCode, professionalById } from '../domain/dataset';
import MunicipalMap from './MunicipalMap';
import Chart, { barOption, chartColors, comboOption, heatmapOption, scatterOption } from './Chart';

export interface DomainPanelsProps {
  page: PageId; view: string; scope: Scope; metrics: Metrics;
  onSubset: (ids: string[], label: string, reason: string) => void;
  onCity: (id: string) => void; onCnae: (code: string) => void; onCbo: (codes: string[]) => void;
  onCompany: (id: string) => void; onInfo: (id: string) => void;
  financialAllowed: boolean;
}
const num = (value: number, digits = 0) => value.toLocaleString('pt-BR', { maximumFractionDigits: digits });
const money = (value: number) => value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const pct = (value: number) => `${num(value, 1)}%`;
const date = (value?: string) => value ? value.slice(0, 10).split('-').reverse().join('/') : '—';
const days = (first: string, last: string) => Math.max(0, Math.floor((Date.parse(`${last}T00:00:00Z`) - Date.parse(`${first}T00:00:00Z`)) / 86400000));
const total = <T,>(rows: T[], fn: (row: T) => number) => rows.reduce((sum, row) => sum + fn(row), 0);
const distinct = <T,>(rows: T[], fn: (row: T) => string) => [...new Set(rows.map(fn))];
const mean = (values: number[]) => values.length ? total(values, value => value) / values.length : 0;
const median = (values: number[]) => { const sorted = [...values].sort((a, b) => a - b); return sorted.length ? (sorted[Math.floor((sorted.length - 1) / 2)] + sorted[Math.floor(sorted.length / 2)]) / 2 : 0; };
const companyName = (id: string) => companyById.get(id)?.name ?? id;
const companyIds = <T extends { companyId: string },>(rows: T[]) => distinct(rows, row => row.companyId);
const bucketCounts = <T,>(rows: T[], key: (row: T) => string, value: (row: T) => number = () => 1) => {
  const map = new Map<string, number>();
  rows.forEach(row => { const label = key(row); map.set(label, (map.get(label) ?? 0) + value(row)); });
  return [...map].map(([label, count]) => ({ label, value: count })).sort((a, b) => b.value - a.value || a.label.localeCompare(b.label, 'pt-BR'));
};

// Financial and acervo summaries attribute each root once, to a visible matrix
// or the first visible establishment. A branch never multiplies a root's facts.
function representativeEstablishments(scope: Scope) {
  const rows = new Map<string, Scope['establishments'][number]>();
  for (const row of scope.establishments) if (!rows.has(row.companyId) || row.branch === 'Matriz') rows.set(row.companyId, row);
  return rows;
}

function Panel({ title, subtitle, children, actions, info, onInfo }: { title: string; subtitle?: string; children: ReactNode; actions?: ReactNode; info?: string; onInfo?: (id: string) => void }) {
  return <section className="p-panel"><header className="p-panel-header"><div><h2 className="p-panel-title">{title}</h2>{subtitle && <p className="p-panel-subtitle">{subtitle}</p>}</div><div className="p-controls">{actions}{info && onInfo && <button className="p-iconbutton" aria-label={`Definição: ${title}`} onClick={() => onInfo(info)}><CircleHelp size={15} /></button>}</div></header><div className="p-panel-body">{children}</div></section>;
}
function SmallStats({ rows, onInfo }: { rows: [string, string, string?][]; onInfo: (id: string) => void }) {
  return <div className="p-mini-stats">{rows.map(([label, value, info]) => <div className="p-mini-stat" key={label}><span>{label}{info && <button className="p-iconbutton" aria-label={`Definição: ${label}`} onClick={() => onInfo(info)}><CircleHelp size={13} /></button>}</span><strong>{value}</strong></div>)}</div>;
}
function Notice({ children }: { children: ReactNode }) { return <div className="p-notice"><CircleHelp size={17} /><p>{children}</p></div>; }
function Toggle({ value, set, choices, label }: { value: string; set: (value: string) => void; choices: [string, string][]; label: string }) {
  return <div className="p-toggle" role="group" aria-label={label}>{choices.map(([id, title]) => <button key={id} aria-pressed={value === id} className={value === id ? 'active' : ''} onClick={() => set(id)}>{title}</button>)}</div>;
}
function companyButton(id: string, onCompany: (id: string) => void, label?: string) {
  return <button className="p-company-link" onClick={() => onCompany(id)}>{label ?? companyName(id)}</button>;
}
type RecordRow = { id: string; cells: ReactNode[]; search: string; status?: string; date?: string; rank?: number };
function Records({ title, subtitle, headers, rows, statuses = [], initialSort = 'date' }: { title: string; subtitle: string; headers: string[]; rows: RecordRow[]; statuses?: string[]; initialSort?: string }) {
  const [query, setQuery] = useState(''); const [status, setStatus] = useState(''); const [sort, setSort] = useState(initialSort); const [page, setPage] = useState(1);
  const rowSignature = rows.map(row => row.id).join('|');
  useEffect(() => { setPage(1); }, [rowSignature, query, status, sort]);
  useEffect(() => { setQuery(''); setStatus(''); setSort(initialSort); setPage(1); }, [title, initialSort]);
  const filtered = useMemo(() => rows.filter(row => (!status || row.status === status) && (!query || row.search.toLocaleLowerCase('pt-BR').includes(query.trim().toLocaleLowerCase('pt-BR')))).sort((a, b) => sort === 'rank' ? (b.rank ?? 0) - (a.rank ?? 0) : sort === 'name' ? a.search.localeCompare(b.search, 'pt-BR') : (b.date ?? '').localeCompare(a.date ?? '')), [rows, query, status, sort]);
  const pages = Math.max(1, Math.ceil(filtered.length / 8));
  return <details className="p-origin-records"><summary>Registros de origem · {title} <span>{num(filtered.length)}</span></summary><section className="p-table-panel"><div className="p-table-tools"><div><h2>{title} <span className="p-count">{num(filtered.length)}</span></h2><p>{subtitle}</p></div><div className="p-controls"><label className="p-search"><Search size={15} /><input aria-label={`Pesquisar ${title.toLowerCase()}`} placeholder="Pesquisar registros" value={query} onChange={event => setQuery(event.target.value)} /></label>{statuses.length > 0 && <select aria-label={`Filtrar situação de ${title.toLowerCase()}`} value={status} onChange={event => setStatus(event.target.value)}><option value="">Todas as situações</option>{statuses.map(value => <option key={value}>{value}</option>)}</select>}<select aria-label={`Ordenar ${title.toLowerCase()}`} value={sort} onChange={event => setSort(event.target.value)}><option value="date">Mais recentes</option><option value="rank">Maior valor / prioridade</option><option value="name">Ordem alfabética</option></select></div></div><div className="p-table-scroll"><table className="p-table"><thead><tr>{headers.map(header => <th key={header}>{header}</th>)}</tr></thead><tbody>{filtered.slice((page - 1) * 8, page * 8).map(row => <tr key={row.id}>{row.cells.map((cell, index) => <td key={index} style={{ whiteSpace: 'normal', maxWidth: index === 0 ? 290 : 380 }}>{cell}</td>)}</tr>)}</tbody></table>{!filtered.length && <div className="p-empty">Nenhum registro corresponde à busca e à situação selecionada.</div>}</div><div className="p-pagination"><span>{num(filtered.length)} registros · 8 por página</span><div><button aria-label={`Página anterior de ${title}`} disabled={page === 1} onClick={() => setPage(value => value - 1)}><ChevronLeft size={15} /></button><span>{page} / {pages}</span><button aria-label={`Próxima página de ${title}`} disabled={page >= pages} onClick={() => setPage(value => value + 1)}><ChevronRight size={15} /></button></div></div></section></details>;
}
function lineOption(labels: string[], series: { name: string; values: number[]; type?: 'line' | 'bar'; axis?: number }[], axes = ['Quantidade']): Record<string, unknown> {
  return { grid: { left: 12, right: 18, top: 36, bottom: 58, containLabel: true }, tooltip: { trigger: 'axis' }, legend: { bottom: 0, textStyle: { fontSize: 12 } }, xAxis: { type: 'category', data: labels, axisLabel: { fontSize: 12 }, axisTick: { show: false } }, yAxis: axes.map((name, index) => ({ type: 'value', name, splitLine: { show: index === 0, lineStyle: { color: '#EDF0F6' } }, axisLabel: { fontSize: 12 } })), series: series.map((row, index) => ({ name: row.name, type: row.type ?? 'line', data: row.values, yAxisIndex: row.axis ?? 0, smooth: false, symbolSize: 5, barMaxWidth: 20, lineStyle: { width: 2.5 }, itemStyle: { color: chartColors[index % chartColors.length] } })) };
}

function RegistryPanels(props: DomainPanelsProps) {
  const { scope, metrics: m, view, onSubset, onInfo, onCompany, onCnae } = props;
  const [grain, setGrain] = useState('month'); const [mode, setMode] = useState('flow'); const [activity, setActivity] = useState('principal');
  const series = useMemo(() => makeSeries(scope, scope.filters.period, grain as 'month' | 'quarter' | 'year'), [scope, grain]);
  const grouped = useMemo(() => ({ size: group(scope, 'size'), nature: group(scope, 'nature') }), [scope]);
  const establishmentCounts = useMemo(() => { const map = new Map<string, number>(); for (const row of scope.establishments) map.set(row.companyId, (map.get(row.companyId) ?? 0) + 1); return map; }, [scope]);
  const registryIndex = useMemo(() => {
    const registered = new Set<string>(); const active = new Set<string>(); const counts = new Map<string, number>();
    for (const row of scope.registrations) { registered.add(row.companyId); if (row.status === 'Ativo') active.add(row.companyId); counts.set(row.companyId, (counts.get(row.companyId) ?? 0) + 1); }
    const latest = new Map<string, Scope['movements'][number]>();
    for (const row of scope.dataset.movements) if (scope.companyIds.has(row.companyId) && (!latest.has(row.companyId) || latest.get(row.companyId)!.date < row.date)) latest.set(row.companyId, row);
    return { registered, active, counts, latest };
  }, [scope]);
  if (view === 'movimentacao') {
    const flowOption = mode === 'stock' ? lineOption(series.map(point => point.label), [{ name: 'Registros ativos ao fim do período', values: series.map(point => point.base) }])
      : lineOption(series.map(point => point.label), [{ name: 'Novos registros', values: series.map(point => point.newRegistrations), type: 'bar' }, { name: 'Baixas', values: series.map(point => point.closures), type: 'bar' }, { name: 'Reativações', values: series.map(point => point.reactivations) }, { name: 'Cancelamentos', values: series.map(point => point.cancellations) }]);
    const tenure = ['Até 1 ano', '1 a 3 anos', 'Mais de 3 anos'];
    const tenureKey = (row: Scope['registrations'][number]) => { const age = days(row.startedAt, row.ceasedAt ?? scope.anchor); return age <= 365 ? tenure[0] : age <= 1095 ? tenure[1] : tenure[2]; };
    return <><SmallStats onInfo={onInfo} rows={[["Baixas no período", num(m.closures), 'closures'], ['Reativações', num(m.reactivations), 'reactivations'], ['Cancelamentos', num(m.cancellations), 'cancellations'], ['Prazo médio / mediano para registro', `${num(m.registrationDaysMean, 1)} / ${num(m.registrationDaysMedian, 1)} dias`, 'registrationDaysMean'], ['Permanência média', `${num(m.tenureMonths, 1)} meses`, 'tenureMonths']]} /><div className="p-grid two"><Panel title="Movimentos e estoque de registros" subtitle="O saldo cadastral soma novos e reativados, deduzindo baixas e cancelamentos." info="net" onInfo={onInfo} actions={<><Toggle value={mode} set={setMode} label="Série cadastral" choices={[["flow", 'Movimentos'], ['stock', 'Estoque']]} /><Toggle value={grain} set={setGrain} label="Granularidade" choices={[["month", 'Mês'], ['quarter', 'Trimestre'], ['year', 'Ano']]} /></>}><Chart option={flowOption} height={345} ariaLabel="Evolução dos registros e seus movimentos" onPick={params => { const point = series[params.dataIndex]; if (!point) return; const end = series[params.dataIndex + 1]?.date ?? '2026-10-01'; onSubset(companyIds(scope.movements.filter(row => row.date >= point.date && row.date < end)), `Movimentos · ${point.label}`, 'Empresas com movimentação de registro na faixa selecionada.'); }} summary={`Saldo do recorte: ${num(m.net)} registros. Estoque e fluxo usam o mesmo histórico de movimentos.`} /></Panel><Panel title="Tempo de permanência no cadastro" subtitle="Registros vigentes e históricos encerrados; clique para explorar as empresas." info="tenureMonths" onInfo={onInfo}><Chart option={barOption(tenure.map(label => ({ label, value: scope.registrations.filter(row => tenureKey(row) === label).length })), 'Registros')} height={345} ariaLabel="Registros por tempo de permanência" onPick={params => onSubset(companyIds(scope.registrations.filter(row => tenureKey(row) === tenure[params.dataIndex])), tenure[params.dataIndex], 'Duração do registro até o encerramento ou a competência.')} /></Panel></div></>;
  }
  if (view === 'perfil') {
    const activities = bucketCounts(scope.establishments.flatMap(row => activity === 'principal' ? [{ code: row.cnaeMain, companyId: row.companyId }] : row.cnaeSecondary.map(code => ({ code, companyId: row.companyId }))), row => row.code);
    return <><div className="p-grid two">{(['size', 'nature'] as const).map(key => <Panel key={key} title={key === 'size' ? 'Porte das empresas' : 'Natureza jurídica'} subtitle="Empresas distintas, sem repetir matriz e filiais." info="companies" onInfo={onInfo}><Chart option={barOption(grouped[key].map(row => ({ label: row.label, value: row.companies })), 'Empresas')} height={310} ariaLabel={`Empresas por ${key === 'size' ? 'porte' : 'natureza jurídica'}`} onPick={params => { const selected = grouped[key][params.dataIndex]; if (selected) onSubset(scope.companies.filter(row => (key === 'size' ? row.size : row.legalNature) === selected.id).map(row => row.id), selected.label, 'Recorte do perfil cadastral empresarial.'); }} /></Panel>)}</div><div className="p-grid"><Panel title="Atividades principais e secundárias" subtitle="Contagem de ocorrências nos estabelecimentos; atividades secundárias não são somadas como novas empresas." actions={<Toggle value={activity} set={setActivity} label="Tipo de atividade" choices={[["principal", 'Principal'], ['secundaria', 'Secundárias']]} />}><Chart option={barOption(activities.slice(0, 12).map(row => ({ label: `${row.label} · ${cnaeByCode.get(row.label)?.label ?? ''}`, value: row.value })), 'Ocorrências cadastrais')} height={390} ariaLabel="Atividades principais e secundárias dos estabelecimentos" onPick={params => { const row = activities[params.dataIndex]; if (row) onCnae(row.label); }} /></Panel></div></>;
  }
  if (view === 'qualidade') {
    const kinds: QualityKind[] = ['CNPJ inválido', 'CNPJ duplicado na origem', 'Sem CNAE', 'Município divergente', 'GRE não identificada', 'CREA ativo / CNPJ baixado', 'CNAE alterado', 'Dados desatualizados'];
    return <><Notice>Defeitos da origem permanecem rastreáveis. CNPJ inválido ou duplicado na origem não cria uma nova identidade no cadastro mestre. Divergências exigem conferência.</Notice><div className="p-grid two"><Panel title="Oito verificações de qualidade" subtitle="Todos os tipos, incluindo eventos já resolvidos. Clique para investigar a origem." info="qualityScore" onInfo={onInfo}><Chart option={barOption(kinds.map(label => ({ label, value: scope.qualityEvents.filter(row => row.type === label).length })), 'Eventos')} height={370} ariaLabel="Eventos nas oito verificações de qualidade" onPick={params => onSubset(companyIds(scope.qualityEvents.filter(row => row.type === kinds[params.dataIndex])), kinds[params.dataIndex], 'Eventos de qualidade, sem inferência de irregularidade.')} /></Panel><Panel title="Eventos e empresas afetadas" subtitle="Um estabelecimento pode concentrar mais de um tipo de evento."><SmallStats onInfo={onInfo} rows={[["Eventos não resolvidos", num(m.qualityEvents), 'qualityEvents'], ['Empresas com evento aberto', num(companyIds(scope.qualityEvents.filter(row => !row.resolved)).length)], ['Estabelecimentos afetados', num(distinct(scope.qualityEvents.filter(row => !row.resolved), row => row.establishmentId).length)], ['Resolvidos', num(scope.qualityEvents.filter(row => row.resolved).length)], ['Consistência do cadastro', pct(m.qualityScore), 'qualityScore']]} /><p className="p-chart-summary">O índice usa estabelecimentos sem eventos abertos ÷ estabelecimentos selecionados. Linhas inválidas e duplicadas são problemas da origem simulada, enquanto o mestre mantém identificação válida e única.</p></Panel></div><Records title="Evidências de qualidade cadastral" subtitle="Origem e evidência preservadas por evento; abra a empresa para conferir o contexto." headers={['Evento / empresa', 'Tipo', 'Origem e evidência', 'Situação', 'Detecção']} statuses={['Aberto', 'Resolvido']} rows={scope.qualityEvents.map(row => ({ id: row.id, date: row.date, status: row.resolved ? 'Resolvido' : 'Aberto', search: `${companyName(row.companyId)} ${row.type} ${row.source} ${row.evidence}`, cells: [<>{companyButton(row.companyId, onCompany)}<small>{row.id} · {row.establishmentId}</small></>, row.type, <>{row.source}<small style={{ maxWidth: 430, whiteSpace: 'normal' }}>{row.evidence}</small></>, row.resolved ? 'Resolvido' : 'Aberto', date(row.date)] }))} /></>;
  }
  const statuses = [{ label: 'Com registro ativo', ids: [...registryIndex.active] }, { label: 'Somente inativo / cancelado', ids: scope.companies.filter(row => registryIndex.registered.has(row.id) && !registryIndex.active.has(row.id)).map(row => row.id) }, { label: 'Sem correspondência CREA', ids: scope.companies.filter(row => !registryIndex.registered.has(row.id)).map(row => row.id) }];
  return <><div className="p-grid two"><Panel title="Empresa → estabelecimentos → registros" subtitle="Cada nível possui sua própria chave e seu denominador." info="registrations" onInfo={onInfo}><div className="p-hierarchy"><button className="p-hierarchy-node" onClick={() => onSubset(scope.companies.map(row => row.id), 'Todas as empresas do recorte', 'Raízes CNPJ distintas.')}><strong>{num(m.companies)} empresas</strong><span>Raiz CNPJ</span><ArrowUpRight size={15} /></button><button className="p-hierarchy-node" onClick={() => onSubset(scope.establishments.filter(row => row.branch === 'Filial').map(row => row.companyId), 'Empresas com filiais', 'CNPJs completos de estabelecimentos distintos.')}><strong>{num(m.establishments)} estabelecimentos</strong><span>{num(scope.establishments.filter(row => row.branch === 'Matriz').length)} matrizes · {num(scope.establishments.filter(row => row.branch === 'Filial').length)} filiais</span></button><button className="p-hierarchy-node" onClick={() => onSubset(companyIds(scope.registrations), 'Empresas localizadas no cadastro CREA', 'Inclui registros ativos, inativos e cancelados.')}><strong>{num(m.registrations)} registros / vistos</strong><span>{num(m.activeRegistrations)} ativos · {num(m.inactiveRegistrations + m.cancelledRegistrations)} encerrados</span></button></div><p className="p-chart-summary">Registros históricos e reativações são preservados. Registro ativo não equivale a comprovação geral de regularidade.</p></Panel><Panel title="Correspondência por empresa" subtitle="Classes mutuamente exclusivas na competência." info="coverage" onInfo={onInfo}><Chart option={barOption(statuses.map(row => ({ label: row.label, value: row.ids.length })), 'Empresas')} height={260} ariaLabel="Correspondência e situação de registro por empresa" onPick={params => { const row = statuses[params.dataIndex]; if (row) onSubset(row.ids, row.label, 'Classificação por existência e situação de registros empresariais.'); }} /></Panel></div><Records title="Empresas com múltiplos estabelecimentos" subtitle="Abra a empresa para percorrer matrizes, filiais, registros vigentes e histórico." headers={['Empresa / raiz CNPJ', 'Estabelecimentos no recorte', 'Registros históricos e atuais', 'Último movimento']} initialSort="rank" rows={scope.companies.filter(row => (establishmentCounts.get(row.id) ?? 0) > 1).map(row => { const latest = registryIndex.latest.get(row.id); return { id: row.id, rank: establishmentCounts.get(row.id), date: latest?.date, search: row.name, cells: [<>{companyButton(row.id, onCompany)}<small>Raiz {row.rootCnpj}</small></>, num(establishmentCounts.get(row.id) ?? 0), num(registryIndex.counts.get(row.id) ?? 0), latest ? `${latest.type} · ${date(latest.date)}` : 'Sem correspondência'] }; })} /></>;
}

function InspectionPanels(props: DomainPanelsProps) {
  const { scope, metrics: m, view, onSubset, onCompany, onInfo } = props;
  const priorities = useMemo(() => new Map(companyIds(scope.cases).map(id => [id, priorityFor(id, scope)])), [scope]);
  const [distribution, setDistribution] = useState('priority');
  const stages = ['Identificada', 'Validação cadastral', 'Análise técnica', 'Encaminhada', 'Concluída'];
  const completed = scope.cases.filter(row => row.status === 'Concluída' && inWindow(row.completedAt, scope.filters.period, scope.anchor));
  if (view === 'resultados') {
    const outcomes = bucketCounts(completed, row => row.outcome); const durations = completed.map(row => days(row.createdAt, row.completedAt!));
    return <><SmallStats onInfo={onInfo} rows={[["Tempo mediano de conclusão", `${num(median(durations), 1)} dias`], ['Tempo médio', `${num(m.caseDaysMean, 1)} dias`, 'caseDaysMean'], ['Empresas com conclusão', num(companyIds(completed).length)], ['Casos com processo ou notificação', num(scope.cases.filter(row => row.notice).length)]]} /><div className="p-grid two"><Panel title="Resultados documentados" subtitle="Conclusões no período; cada resultado mantém o caso e a empresa de origem."><Chart option={barOption(outcomes, 'Casos concluídos')} height={320} ariaLabel="Resultados dos casos concluídos" onPick={params => { const row = outcomes[params.dataIndex]; if (row) onSubset(companyIds(completed.filter(item => item.outcome === row.label)), row.label, 'Conclusão registrada após tratamento do caso.'); }} /></Panel><Panel title="Duração dos casos concluídos" subtitle="Cada ponto representa um caso. Abra a empresa para consultar suas fases."><Chart option={scatterOption(completed.map(row => ({ label: row.id, x: days(row.createdAt, row.completedAt!), y: priorities.get(row.companyId)?.score ?? 0 })), 'Dias de tratamento', 'Prioridade demonstrativa')} height={320} ariaLabel="Prazo de conclusão e prioridade dos casos" onPick={params => { const row = completed[params.dataIndex]; if (row) onCompany(row.companyId); }} /></Panel></div><Records title="Conclusões de fiscalização" subtitle="Resultados e datas demonstrativos; não são autos ou decisões reais." headers={['Caso / empresa', 'Identificação', 'Conclusão', 'Dias', 'Resultado']} rows={completed.map(row => ({ id: row.id, date: row.completedAt, rank: days(row.createdAt, row.completedAt!), search: `${row.id} ${companyName(row.companyId)} ${row.outcome}`, cells: [<>{companyButton(row.companyId, onCompany, row.id)}<small>{companyName(row.companyId)}</small></>, date(row.createdAt), date(row.completedAt), num(days(row.createdAt, row.completedAt!)), row.outcome] }))} /></>;
  }
  const cases = view === 'priorizacao' ? scope.cases.filter(row => row.status !== 'Concluída') : scope.cases;
  const greCases = bucketCounts(cases, row => establishmentById.get(row.establishmentId)?.greId ?? 'Não identificada');
  const chartRows = distribution === 'gre' ? greCases.map(row => ({ label: greById.get(row.label)?.name ?? row.label, value: row.value })) : view === 'fluxo' ? stages.map(label => ({ label, value: cases.filter(row => row.status === label).length })) : ['Alta', 'Média', 'Baixa'].map(label => ({ label, value: cases.filter(row => priorities.get(row.companyId)?.level === label).length }));
  return <><Notice>A pontuação organiza verificações e apresenta os fatores utilizados. Ausência de correspondência ou CNAE relacionado não determina irregularidade, obrigação ou autuação.</Notice><div className="p-grid two"><Panel title={distribution === 'gre' ? 'Casos distribuídos por GRE' : view === 'fluxo' ? 'Fluxo de triagem e análise' : 'Prioridade de verificação'} subtitle={view === 'fluxo' ? 'Situação atual dos casos; clique em uma fase ou GRE para percorrer suas empresas.' : 'Regras explicáveis, versão 1.0; casos abertos e território do estabelecimento.'} info={view === 'fluxo' ? 'caseCount' : 'priority'} onInfo={onInfo} actions={<Toggle value={distribution} set={setDistribution} label="Distribuição dos casos" choices={[["priority", view === 'fluxo' ? 'Fase' : 'Prioridade'], ['gre', 'GRE']]} />}><Chart option={barOption(chartRows, 'Casos')} height={300} ariaLabel={distribution === 'gre' ? 'Casos por GRE' : 'Fila e prioridade de verificação'} onPick={params => { const selected = chartRows[params.dataIndex]; if (!selected) return; const ids = distribution === 'gre' ? companyIds(cases.filter(row => establishmentById.get(row.establishmentId)?.greId === greCases[params.dataIndex]?.label)) : companyIds(cases.filter(row => view === 'fluxo' ? row.status === selected.label : priorities.get(row.companyId)?.level === selected.label)); onSubset(ids, `${distribution === 'gre' ? 'GRE' : view === 'fluxo' ? 'Fase' : 'Prioridade'} · ${selected.label}`, 'Recorte de casos para análise humana, sem conclusão automática de irregularidade.'); }} /></Panel><Panel title="Caso analítico e processo formal" subtitle="Etapas distintas, com datas e identificadores próprios."><SmallStats onInfo={onInfo} rows={[["Encaminhados", num(m.forwardedCases), 'forwardedCases'], ['Concluídos no período', num(m.completedCases), 'completedCases'], ['Com notificação ou processo', num(scope.cases.filter(row => row.notice).length)], ['Sem processo formal identificado', num(scope.cases.filter(row => !row.notice).length)]]} /><p className="p-chart-summary">“Abrir caso” consulta a empresa, os fatores e o histórico. O protótipo não emite notificações, autos ou decisões. Um caso identificado pode encerrar-se após atualização cadastral.</p></Panel></div><Records title={view === 'fluxo' ? 'Histórico e fases dos casos' : 'Fila de casos priorizados'} subtitle="Busca por caso ou empresa; filtros de fase e ordenação por prioridade." headers={['Caso / empresa', 'Município / GRE / CNAE', 'Fase e datas', 'Prioridade e fatores', 'Processo / encaminhamento', 'Consulta']} statuses={stages} initialSort={view === 'priorizacao' ? 'rank' : 'date'} rows={cases.map(row => { const priority = priorities.get(row.companyId)!; const establishment = establishmentById.get(row.establishmentId); return { id: row.id, status: row.status, date: row.history.at(-1)?.date, rank: priority.score, search: `${row.id} ${companyName(row.companyId)} ${row.status} ${cityById.get(establishment?.cityId ?? '')?.name} ${establishment?.cnaeMain}`, cells: [<>{row.id}<small>{companyName(row.companyId)}</small></>, <>{cityById.get(establishment?.cityId ?? '')?.name}<small>{greById.get(establishment?.greId ?? '')?.name}</small><small>CNAE {establishment?.cnaeMain} · {cnaeByCode.get(establishment?.cnaeMain ?? '')?.label}</small></>, <>{row.status}<small>Identificação {date(row.createdAt)}</small><details><summary>Histórico de {row.history.length} fases</summary><ol className="p-detail-list">{row.history.map(entry => <li key={entry.status}><strong>{date(entry.date)} · {entry.status}</strong><p>{entry.note}</p></li>)}</ol></details></>, <><span className="p-badge">{priority.score} / 100 · {priority.level}</span><details><summary>Por que esta prioridade?</summary><ul className="p-priority-factors">{priority.factors.map(factor => <li key={factor.label}><strong>{factor.points > 0 ? '+' : ''}{factor.points} · {factor.label}</strong><p>{factor.evidence}</p></li>)}</ul><p>{priority.limitation}</p></details></>, row.notice ? <>{row.notice.stage}<small>{row.notice.id} · {date(row.notice.date)}</small></> : 'Sem processo formal', <button className="p-secondary" onClick={() => onCompany(row.companyId)}>Abrir caso <ArrowUpRight size={13} /></button>] }; })} /></>;
}

function TechnicalPanels(props: DomainPanelsProps) {
  const { scope, metrics: m, view, onSubset, onCompany, onInfo } = props;
  const active = useMemo(() => scope.technicalLinks.filter(row => isActiveLink(row, scope.anchor)), [scope]);
  const [grain, setGrain] = useState('month'); const [matrixLevel, setMatrixLevel] = useState('company'); const [rankingLevel, setRankingLevel] = useState('company');
  const replacements = useMemo(() => scope.technicalLinks.filter(next => inWindow(next.startDate, scope.filters.period, scope.anchor) && scope.technicalLinks.some(previous => previous.companyId === next.companyId && previous.professionalId !== next.professionalId && !!previous.endDate && previous.endDate < next.startDate)), [scope]);
  const series = useMemo(() => makeSeries(scope, scope.filters.period, grain as 'month' | 'quarter' | 'year'), [scope, grain]);
  if (view === 'modalidades') {
    const modalities = [...new Set(active.map(row => row.modality))].sort(); const sizes = ['Microempresa', 'Pequena empresa', 'Média empresa', 'Grande empresa'];
    const companies = bucketCounts(active, row => row.companyId).slice(0, 12);
    const matrix: [number, number, number][] = matrixLevel === 'company' ? companies.flatMap((company, y) => modalities.map((modality, x) => [x, y, active.filter(row => row.companyId === company.label && row.modality === modality).length] as [number, number, number])) : modalities.flatMap((modality, y) => sizes.map((size, x) => [x, y, companyIds(active.filter(row => row.modality === modality && companyById.get(row.companyId)?.size === size)).length] as [number, number, number]));
    const modalitiesRank = bucketCounts(active, row => row.modality);
    return <><Notice>Empresa, vínculo e profissional são unidades distintas. Uma empresa pode ter várias modalidades; um profissional pode responder por mais de uma empresa.</Notice><div className="p-grid two"><Panel title={matrixLevel === 'company' ? 'Empresa × modalidade profissional' : 'Modalidades × porte empresarial'} subtitle={matrixLevel === 'company' ? 'Até 12 empresas com mais vínculos vigentes; cada célula conta vínculos. Clique para explorar a combinação.' : 'Empresas distintas por célula; modalidades podem se sobrepor.'} info="multiRt" onInfo={onInfo} actions={<Toggle value={matrixLevel} set={setMatrixLevel} label="Nível da matriz de modalidades" choices={[["company", 'Empresa'], ['size', 'Porte']]} />}><Chart option={heatmapOption(matrixLevel === 'company' ? modalities : sizes, matrixLevel === 'company' ? companies.map(row => companyName(row.label)) : modalities, matrix)} height={390} ariaLabel={matrixLevel === 'company' ? 'Matriz de vínculos vigentes por empresa e modalidade' : 'Empresas por modalidade profissional e porte'} onPick={params => { const [x, y] = params.value; if (matrixLevel === 'company') { const company = companies[y]; const modality = modalities[x]; if (company && modality) onSubset(companyIds(active.filter(row => row.companyId === company.label && row.modality === modality)), `${companyName(company.label)} · ${modality}`, 'Vínculos vigentes da empresa e modalidade selecionadas.'); } else onSubset(companyIds(active.filter(row => row.modality === modalities[y] && companyById.get(row.companyId)?.size === sizes[x])), `${modalities[y]} · ${sizes[x]}`, 'Empresas com ao menos um vínculo vigente na modalidade selecionada.'); }} /></Panel><Panel title="Modalidades dos vínculos vigentes" subtitle="Contagem de vínculos técnicos; pessoas e empresas distintas podem aparecer em mais de uma modalidade."><Chart option={barOption(modalitiesRank, 'Vínculos vigentes')} height={390} ariaLabel="Ranking de modalidades dos vínculos técnicos" onPick={params => { const selected = modalitiesRank[params.dataIndex]; if (selected) onSubset(companyIds(active.filter(row => row.modality === selected.label)), selected.label, 'Empresas com vínculo vigente na modalidade selecionada.'); }} /></Panel></div></>;
  }
  if (view === 'evolucao') {
    const activeAt = series.map((point, index) => { const next = series[index + 1]?.date ?? '2026-10-01'; const cutoff = new Date(Date.parse(`${next}T00:00:00Z`) - 86400000).toISOString().slice(0, 10); return scope.technicalLinks.filter(row => isActiveLink(row, cutoff)).length; });
    return <><SmallStats onInfo={onInfo} rows={[["Entradas de vínculos", num(m.newLinks), 'newLinks'], ['Encerramentos', num(m.closedLinks), 'closedLinks'], ['Saldo de vínculos', num(m.newLinks - m.closedLinks)], ['Trocas identificadas no período', num(replacements.length), 'rtChanges'], ['Vigência média atual', `${num(m.linkDaysMean, 1)} dias`, 'linkDaysMean']]} /><div className="p-grid two"><Panel title="Entradas, encerramentos e estoque de vínculos" subtitle="Datas de início e fim preservadas para cada vínculo." actions={<Toggle value={grain} set={setGrain} label="Granularidade de vínculos" choices={[["month", 'Mês'], ['quarter', 'Trimestre'], ['year', 'Ano']]} />}><Chart option={lineOption(series.map(row => row.label), [{ name: 'Novos vínculos', values: series.map(row => row.newLinks), type: 'bar' }, { name: 'Encerrados', values: series.map(row => row.closedLinks), type: 'bar' }, { name: 'Vínculos ativos', values: activeAt, axis: 1 }], ['Movimentos', 'Estoque'])} height={335} ariaLabel="Evolução temporal da responsabilidade técnica" onPick={params => { const point = series[params.dataIndex]; if (!point) return; const next = series[params.dataIndex + 1]?.date ?? '2026-10-01'; onSubset(companyIds(scope.technicalLinks.filter(row => row.startDate >= point.date && row.startDate < next || !!row.endDate && row.endDate >= point.date && row.endDate < next)), `Vínculos · ${point.label}`, 'Entradas ou encerramentos no intervalo selecionado.'); }} /></Panel><Panel title="ARTs e modalidades no período" subtitle="ART é registro de atividade; valores declarados não representam receita do conselho." info="arts" onInfo={onInfo}><Chart option={barOption(bucketCounts(scope.arts, row => row.modality), 'ARTs')} height={335} ariaLabel="ARTs por modalidade profissional" onPick={params => { const row = bucketCounts(scope.arts, item => item.modality)[params.dataIndex]; if (row) onSubset(companyIds(scope.arts.filter(item => item.modality === row.label)), `ART · ${row.label}`, 'Empresas com ART da modalidade registrada no período.'); }} /></Panel></div><Records title="Histórico dos vínculos técnicos" subtitle="Início, encerramento e modalidade; vínculos encerrados permanecem no histórico." headers={['Empresa', 'Profissional / modalidade', 'Início', 'Encerramento', 'Situação']} statuses={['Vigente', 'Encerrado']} rows={scope.technicalLinks.map(row => ({ id: row.id, date: row.startDate, status: isActiveLink(row, scope.anchor) ? 'Vigente' : 'Encerrado', search: `${companyName(row.companyId)} ${professionalById.get(row.professionalId)?.name} ${row.modality}`, cells: [companyButton(row.companyId, onCompany), <>{professionalById.get(row.professionalId)?.name}<small>{row.modality} · {row.id}</small></>, date(row.startDate), date(row.endDate), isActiveLink(row, scope.anchor) ? 'Vigente' : 'Encerrado'] }))} /></>;
  }
  const linksPerCompany = new Map<string, number>(); for (const row of active) linksPerCompany.set(row.companyId, (linksPerCompany.get(row.companyId) ?? 0) + 1);
  const registered = new Set(scope.registrations.map(row => row.companyId)); const groups = [{ label: 'Um vínculo vigente', ids: [...registered].filter(id => linksPerCompany.get(id) === 1) }, { label: 'Múltiplos vínculos vigentes', ids: [...registered].filter(id => (linksPerCompany.get(id) ?? 0) > 1) }];
  const professionalRows = [...new Set(active.map(row => row.professionalId))].map(id => ({ id, links: active.filter(row => row.professionalId === id), historical: scope.technicalLinks.filter(row => row.professionalId === id) })).sort((a, b) => companyIds(b.links).length - companyIds(a.links).length);
  const companiesRank = [...linksPerCompany].map(([id, value]) => ({ id, label: companyName(id), value })).sort((a, b) => b.value - a.value || a.label.localeCompare(b.label));
  const ranking = rankingLevel === 'company' ? companiesRank : professionalRows.map(row => ({ id: row.id, label: professionalById.get(row.id)?.name ?? row.id, value: companyIds(row.links).length }));
  return <><SmallStats onInfo={onInfo} rows={[["Trocas identificadas no período", num(replacements.length), 'rtChanges'], ["Profissionais distintos", num(m.distinctProfessionals), 'distinctProfessionals'], ['Vínculos vigentes', num(m.activeLinks), 'activeLinks'], ['Empresas com múltiplos vínculos', num(m.multiRt), 'multiRt']]} /><div className="p-grid two"><Panel title="Responsabilidade técnica por empresa" subtitle="Empresas com vínculos vigentes; cada empresa entra em uma faixa de quantidade." info="withRt" onInfo={onInfo}><Chart option={barOption(groups.map(row => ({ label: row.label, value: row.ids.length })), 'Empresas')} height={310} ariaLabel="Empresas por quantidade de vínculos técnicos vigentes" onPick={params => { const row = groups[params.dataIndex]; if (row) onSubset(row.ids, row.label, 'Contagem de vínculos técnicos vigentes por empresa localizada.'); }} /></Panel><Panel title={rankingLevel === 'company' ? 'Empresas com mais vínculos técnicos' : 'Concentração de vínculos profissionais'} subtitle={rankingLevel === 'company' ? 'Vínculos vigentes por empresa distinta; clique para consultar a ficha.' : 'Empresas distintas por profissional; sem limite regulatório presumido.'} actions={<Toggle value={rankingLevel} set={setRankingLevel} label="Unidade do ranking de vínculos" choices={[["company", 'Empresas'], ['professional', 'Profissionais']]} />}><Chart option={barOption(ranking.slice(0, 8), rankingLevel === 'company' ? 'Vínculos vigentes' : 'Empresas vinculadas')} height={310} ariaLabel={rankingLevel === 'company' ? 'Empresas com maior número de vínculos técnicos vigentes' : 'Concentração de empresas por profissional'} onPick={params => { const row = ranking[params.dataIndex]; if (!row) return; if (rankingLevel === 'company') onCompany(row.id); else onSubset(companyIds(active.filter(link => link.professionalId === row.id)), `Profissional · ${row.label}`, 'Empresas vinculadas ao mesmo profissional no snapshot.'); }} /></Panel></div><Records title="Profissionais e seu histórico empresarial" subtitle="Pessoas distintas e empresas vinculadas em colunas separadas. Troca = novo vínculo no período com profissional diferente de um vínculo anterior encerrado antes do início; não implica substituição formal comprovada." headers={['Profissional', 'Modalidade', 'Empresas com vínculo vigente', 'Vínculos vigentes / históricos', 'Explorar empresas']} initialSort="rank" rows={professionalRows.map(row => ({ id: row.id, rank: companyIds(row.links).length, search: professionalById.get(row.id)?.name ?? row.id, cells: [professionalById.get(row.id)?.name, professionalById.get(row.id)?.modality, num(companyIds(row.links).length), `${row.links.length} / ${row.historical.length}`, <button className="p-secondary" onClick={() => onSubset(companyIds(row.links), `Profissional · ${professionalById.get(row.id)?.name}`, 'Seleção explícita de empresas com vínculo técnico vigente.')}>Explorar <ArrowUpRight size={13} /></button>] }))} /></>;
}

function CaoPanels(props: DomainPanelsProps) {
  const { scope, metrics: m, view, onSubset, onCompany, onInfo } = props;
  const [acervoDimension, setAcervoDimension] = useState('modality');
  const representatives = useMemo(() => representativeEstablishments(scope), [scope]);
  const issued = scope.caos.filter(row => inWindow(row.issuedAt, scope.filters.period, scope.anchor));
  const statuses = ['Solicitada', 'Em análise', 'Pendente', 'Emitida', 'Revogada'];
  const series = useMemo(() => makeSeries(scope), [scope]);
  const artsById = useMemo(() => new Map(scope.dataset.arts.map(row => [row.id, row])), [scope.dataset]);
  const pending = scope.caos.filter(row => ['Solicitada', 'Em análise', 'Pendente'].includes(row.status));
  const caoRows = (rows: Scope['caos']) => rows.map(row => ({ id: row.id, date: row.issuedAt ?? row.requestedAt, status: row.status, rank: row.issuedAt ? days(row.requestedAt, row.issuedAt) : days(row.requestedAt, scope.anchor), search: `${row.id} ${companyName(row.companyId)} ${row.activity} ${row.artIds.join(' ')}`, cells: [<>{companyButton(row.companyId, onCompany, row.id)}<small>{companyName(row.companyId)}</small></>, row.status, date(row.requestedAt), date(row.issuedAt), row.issuedAt ? `${days(row.requestedAt, row.issuedAt)} dias` : `${days(row.requestedAt, scope.anchor)} dias em tramitação`, <>{num(row.artIds.length)} ARTs<details><summary>Referências e atividades</summary><p>{row.artIds.join(' · ')}</p><p>{row.activity}</p></details></>] }));
  if (view === 'acervo') {
    const references = new Set(issued.flatMap(row => row.artIds)); const linkedArts = scope.dataset.arts.filter(row => references.has(row.id));
    const dimensionKey = (companyId: string) => acervoDimension === 'city' ? representatives.get(companyId)?.cityId ?? 'Não identificado' : representatives.get(companyId)?.cnaeMain ?? 'Não identificado';
    const dimensions = acervoDimension === 'modality' ? bucketCounts(linkedArts, row => row.modality) : bucketCounts(issued, row => dimensionKey(row.companyId));
    const dimensionLabel = (id: string) => acervoDimension === 'city' ? cityById.get(id)?.name ?? id : acervoDimension === 'cnae' ? `${id} · ${cnaeByCode.get(id)?.label ?? ''}` : id;
    return <><Notice>CAO e ART são entidades distintas. Certidões demonstrativas emitidas referenciam ARTs da mesma empresa com baixa anterior à emissão. Nenhum item constitui documento ou comprovação real de acervo.</Notice><SmallStats onInfo={onInfo} rows={[["Empresas com emissão no período", num(m.caoCompanies), 'caoCompanies'], ['ARTs distintas referenciadas', num(references.size), 'artReferences'], ['Emissões ainda vigentes', num(issued.filter(row => row.status === 'Emitida').length)], ['Emissões hoje revogadas', num(issued.filter(row => row.status === 'Revogada').length), 'caoIssuedRevoked']]} /><div className="p-grid two"><Panel title="Atividades referenciadas no acervo" subtitle="ARTs distintas das CAOs emitidas no período; clique para explorar a empresa."><Chart option={barOption(bucketCounts(linkedArts, row => row.description), 'ARTs referenciadas')} height={330} ariaLabel="Atividades das ARTs vinculadas às CAOs" onPick={params => { const row = bucketCounts(linkedArts, item => item.description)[params.dataIndex]; if (row) onSubset(companyIds(linkedArts.filter(item => item.description === row.label)), row.label, 'Atividades declaradas nas ARTs referenciadas por CAOs emitidas.'); }} /></Panel><Panel title="Distribuição do acervo operacional" subtitle={acervoDimension === 'modality' ? 'ARTs distintas; uma ART relacionada a mais de uma certidão é contada uma vez.' : 'CAOs emitidas no período, incluindo as hoje revogadas. Atribuição única à matriz visível ou primeiro estabelecimento.'} actions={<Toggle value={acervoDimension} set={setAcervoDimension} label="Distribuição do acervo" choices={[["modality", 'Modalidade'], ['city', 'Município'], ['cnae', 'Segmento CNAE']]} />}><Chart option={barOption(dimensions.slice(0, 12).map(row => ({ label: dimensionLabel(row.label), value: row.value })), acervoDimension === 'modality' ? 'ARTs distintas' : 'CAOs emitidas')} height={330} ariaLabel="Modalidades, municípios e segmentos do acervo operacional" onPick={params => { const row = dimensions[params.dataIndex]; if (!row) return; const ids = acervoDimension === 'modality' ? companyIds(linkedArts.filter(item => item.modality === row.label)) : companyIds(issued.filter(item => dimensionKey(item.companyId) === row.label)); onSubset(ids, `Acervo · ${dimensionLabel(row.label)}`, 'Distribuição de acervo por modalidade, município ou CNAE principal da empresa; sem avaliação automática de atribuições.'); }} /></Panel></div><Records title="Relação entre CAO e ART" subtitle="Ponte verificável entre certidão demonstrativa e ARTs; situação atual preservada." headers={['CAO / empresa', 'Situação atual', 'ARTs e baixas anteriores', 'Emissão', 'Atividade']} statuses={statuses} rows={issued.map(row => ({ id: row.id, date: row.issuedAt, status: row.status, search: `${row.id} ${companyName(row.companyId)} ${row.artIds.join(' ')}`, cells: [companyButton(row.companyId, onCompany, row.id), row.status, <>{row.artIds.map(artId => <p key={artId}>{artId}<small>Baixa em {date(artsById.get(artId)?.endDate)}</small></p>)}</>, date(row.issuedAt), row.activity] }))} /></>;
  }
  if (view === 'tramitacao') {
    const ages = ['Até 30 dias', '31–90 dias', '91–365 dias', 'Mais de 365 dias'];
    const ageKey = (requestedAt: string) => { const age = days(requestedAt, scope.anchor); return age <= 30 ? ages[0] : age <= 90 ? ages[1] : age <= 365 ? ages[2] : ages[3]; };
    return <><div className="p-grid two"><Panel title="Situação atual das solicitações" subtitle="Estoque na competência. Revogação não apaga o evento histórico de emissão." info="caoAnalysis" onInfo={onInfo}><Chart option={barOption(statuses.map(label => ({ label, value: scope.caos.filter(row => row.status === label).length })), 'CAOs')} height={340} ariaLabel="Situação atual das solicitações de CAO" onPick={params => onSubset(companyIds(scope.caos.filter(row => row.status === statuses[params.dataIndex])), `CAO · ${statuses[params.dataIndex]}`, 'Situação atual dos processos de acervo operacional.')} /></Panel><Panel title="Idade das solicitações em tramitação" subtitle="Dias desde a solicitação para casos solicitados, em análise ou pendentes."><Chart option={barOption(ages.map(label => ({ label, value: pending.filter(row => ageKey(row.requestedAt) === label).length })), 'Solicitações abertas')} height={340} ariaLabel="Idade dos processos abertos de CAO" onPick={params => onSubset(companyIds(pending.filter(row => ageKey(row.requestedAt) === ages[params.dataIndex])), `CAO em tramitação · ${ages[params.dataIndex]}`, 'Idade de solicitação, sem inferência de descumprimento de prazo institucional.')} /></Panel></div><Records title="Tramitação das CAOs" subtitle="Situação atual, solicitação, emissão e referências documentais demonstrativas." headers={['CAO / empresa', 'Situação', 'Solicitação', 'Emissão', 'Tempo', 'Referências']} statuses={statuses} rows={caoRows(scope.caos)} /></>;
  }
  return <><SmallStats onInfo={onInfo} rows={[["Solicitações no período", num(m.caoRequested), 'caoRequested'], ['Tempo médio / mediano', `${num(m.caoDaysMean, 1)} / ${num(m.caoDaysMedian, 1)} dias`, 'caoDaysMean'], ['Empresas com emissão', num(m.caoCompanies), 'caoCompanies'], ['Revogadas na competência', num(m.caoRevoked), 'caoRevoked']]} /><div className="p-grid two"><Panel title="Solicitações e emissões de CAO" subtitle="Fluxos por datas próprias; emissões incluem certidões posteriormente revogadas." info="caoIssued" onInfo={onInfo}><Chart option={lineOption(series.map(row => row.label), [{ name: 'Solicitações', values: series.map(point => scope.caos.filter(row => row.requestedAt.startsWith(point.date.slice(0, 7))).length), type: 'bar' }, { name: 'Emissões', values: series.map(row => row.caos) }])} height={345} ariaLabel="Solicitações e emissões mensais de CAO" onPick={params => { const point = series[params.dataIndex]; if (point) onSubset(companyIds(scope.caos.filter(row => (params.seriesIndex === 0 ? row.requestedAt : row.issuedAt)?.startsWith(point.date.slice(0, 7)))), `CAO · ${point.label}`, 'Solicitação ou emissão no mês selecionado conforme a série.'); }} /></Panel><Panel title="Tempo de emissão e referências" subtitle="Uma CAO por ponto; clique para consultar a empresa e os documentos associados."><Chart option={scatterOption(issued.map(row => ({ label: `${row.id} · ${date(row.issuedAt)}`, x: days(row.requestedAt, row.issuedAt!), y: row.artIds.length })), 'Dias até a emissão', 'ARTs referenciadas')} height={345} ariaLabel="Tempo de emissão de CAO e quantidade de ARTs vinculadas" onPick={params => { const row = issued[params.dataIndex]; if (row) onCompany(row.companyId); }} /></Panel></div><Records title="CAOs emitidas no período" subtitle="A emissão histórica permanece visível mesmo quando o status atual é revogado." headers={['CAO / empresa', 'Situação atual', 'Solicitação', 'Emissão', 'Tempo', 'Referências']} statuses={['Emitida', 'Revogada']} rows={caoRows(issued)} /></>;
}

function FinancialPanels(props: DomainPanelsProps) {
  const { scope, metrics: m, view, onSubset, onCompany, onInfo } = props;
  const [rateMeasure, setRateMeasure] = useState('compliance'); const [debtDimension, setDebtDimension] = useState('gre');
  const representatives = useMemo(() => representativeEstablishments(scope), [scope]);
  const series = useMemo(() => makeSeries(scope), [scope]);
  const registered = new Set(scope.registrations.map(row => row.companyId));
  const late = scope.invoices.filter(row => row.dueDate < scope.anchor && registered.has(row.companyId) && outstanding(row, scope.anchor) > 0);
  const lateIds = new Set(late.map(row => row.companyId));
  const eligibleIds = new Set(scope.invoices.filter(row => row.dueDate <= scope.anchor && registered.has(row.companyId)).map(row => row.companyId));
  const representativeGre = useMemo(() => { const map = new Map<string, string>(); for (const row of scope.establishments) if (!map.has(row.companyId) || row.branch === 'Matriz') map.set(row.companyId, row.greId); return map; }, [scope]);
  const invoiceStatus = (row: Scope['invoices'][number]) => outstanding(row, scope.anchor) === 0 ? 'Liquidada' : row.dueDate >= scope.anchor ? 'Vincenda' : row.paidAmount > 0 ? 'Parcial' : 'Vencida';
  const invoiceRows = (rows: Scope['invoices']) => rows.map(row => ({ id: row.id, date: row.dueDate, rank: outstanding(row, scope.anchor), status: invoiceStatus(row), search: `${row.id} ${companyName(row.companyId)} ${row.registrationId} ${invoiceStatus(row)}`, cells: [<>{companyButton(row.companyId, onCompany)}<small>{row.id} · {row.registrationId}</small></>, date(row.dueDate), money(row.amount), money(row.paidAmount), money(outstanding(row, scope.anchor)), <>{date(row.paymentDate)}<small>{row.recovered ? 'Recuperação de débito vencido' : row.installmentPlan ? 'Parcelamento' : invoiceStatus(row)}</small></>] }));
  if (view === 'debitos') {
    const buckets = ['Até 30 dias', '31–90 dias', '91–365 dias', 'Mais de 365 dias'];
    const ageKey = (dueDate: string) => { const age = days(dueDate, scope.anchor); return age <= 30 ? buckets[0] : age <= 90 ? buckets[1] : age <= 365 ? buckets[2] : buckets[3]; };
    const dimensionKey = (companyId: string) => debtDimension === 'gre' ? representatives.get(companyId)?.greId ?? 'Não identificada' : debtDimension === 'size' ? companyById.get(companyId)?.size ?? 'Não identificado' : representatives.get(companyId)?.cnaeMain ?? 'Não identificado';
    const dimensionLabel = (id: string) => debtDimension === 'gre' ? greById.get(id)?.name ?? id : debtDimension === 'cnae' ? `${id} · ${cnaeByCode.get(id)?.label ?? ''}` : id;
    const debtValues = bucketCounts(late, row => dimensionKey(row.companyId), row => outstanding(row, scope.anchor));
    return <><SmallStats onInfo={onInfo} rows={[["Obrigações com saldo vencido", num(late.length)], ['Empresas distintas com débito', num(lateIds.size), 'delinquentCompanies'], ['Atraso médio das obrigações', `${num(m.delayDaysMean, 1)} dias`, 'delayDaysMean'], ['Saldo ainda não vencido', money(total(scope.invoices.filter(row => row.dueDate >= scope.anchor), row => outstanding(row, scope.anchor)))]]} /><div className="p-grid two"><Panel title="Envelhecimento dos débitos" subtitle="Saldo residual na competência; pagamento parcial reduz o valor em aberto." info="overdueAmount" onInfo={onInfo}><Chart option={barOption(buckets.map(label => ({ label, value: total(late.filter(row => ageKey(row.dueDate) === label), row => outstanding(row, scope.anchor)) })), 'Saldo vencido (R$)')} height={350} ariaLabel="Saldo devedor por faixa de atraso" onPick={params => onSubset(companyIds(late.filter(row => ageKey(row.dueDate) === buckets[params.dataIndex])), `Débitos · ${buckets[params.dataIndex]}`, 'Obrigações vencidas com saldo residual positivo na competência.')} /></Panel><Panel title="Débito agregado por território e perfil" subtitle="Cada empresa é atribuída à matriz visível, ou ao primeiro estabelecimento do recorte; saldo residual sem duplicar filiais." actions={<Toggle value={debtDimension} set={setDebtDimension} label="Distribuição dos débitos" choices={[["gre", 'GRE'], ['size', 'Porte'], ['cnae', 'CNAE']]} />}><Chart option={barOption(debtValues.slice(0, 12).map(row => ({ label: dimensionLabel(row.label), value: row.value })), 'Saldo vencido (R$)')} height={350} ariaLabel="Ranking regional e empresarial do saldo vencido" onPick={params => { const selected = debtValues[params.dataIndex]; if (selected) onSubset(companyIds(late.filter(row => dimensionKey(row.companyId) === selected.label)), dimensionLabel(selected.label), 'Atribuição única de empresa para apresentação financeira por GRE, porte ou CNAE principal.'); }} /></Panel></div><Records title="Obrigações vencidas e saldos" subtitle="Uma linha por obrigação; consulte a empresa para reunir seus registros e pagamentos." headers={['Empresa / obrigação', 'Vencimento', 'Lançado', 'Pago até a competência', 'Saldo residual', 'Pagamento / condição']} statuses={['Vencida', 'Parcial']} initialSort="rank" rows={invoiceRows(late)} /></>;
  }
  if (view === 'recuperacao') {
    const recovered = scope.invoices.filter(row => row.recovered && inWindow(row.paymentDate, scope.filters.period, scope.anchor));
    const recoveryMonths = series.map(point => total(recovered.filter(row => row.paymentDate?.startsWith(point.date.slice(0, 7))), row => row.paidAmount));
    const parcel = scope.invoices.filter(row => row.installmentPlan && outstanding(row, scope.anchor) > 0);
    return <><SmallStats onInfo={onInfo} rows={[["Recuperado no período", money(m.recoveredAmount), 'recoveredAmount'], ['Empresas com recuperação', num(companyIds(recovered).length)], ['Empresas com parcelamento aberto', num(m.installments), 'installments'], ['Saldo em parcelamento', money(total(parcel, row => outstanding(row, scope.anchor)))]]} /><div className="p-grid two"><Panel title="Recuperação de crédito por pagamento" subtitle="Fluxo no mês de pagamento de obrigação anteriormente vencida." info="recoveredAmount" onInfo={onInfo}><Chart option={lineOption(series.map(row => row.label), [{ name: 'Recuperado (R$)', values: recoveryMonths, type: 'bar' }], ['R$'])} height={330} ariaLabel="Valores recuperados por mês de pagamento" onPick={params => { const point = series[params.dataIndex]; if (point) onSubset(companyIds(recovered.filter(row => row.paymentDate?.startsWith(point.date.slice(0, 7)))), `Recuperação · ${point.label}`, 'Pagamentos de obrigações vencidas marcados como recuperação.'); }} /></Panel><Panel title="Evolução do saldo vencido" subtitle="Snapshot reconstruído ao fim de cada mês, respeitando a data efetiva do pagamento."><Chart option={lineOption(series.map(row => row.label), [{ name: 'Saldo vencido (R$)', values: series.map(row => row.overdue) }], ['R$'])} height={330} ariaLabel="Saldo vencido reconstruído historicamente" summary="O valor pago só reduz o saldo a partir da data do pagamento; não é uma série de lançamentos mensais." /></Panel></div><Records title="Pagamentos e recuperação" subtitle="Data do vencimento e pagamento preservadas; parcelamento é atributo da obrigação." headers={['Empresa / obrigação', 'Vencimento', 'Lançado', 'Pago até a competência', 'Saldo residual', 'Pagamento / condição']} rows={invoiceRows(scope.invoices.filter(row => inWindow(row.paymentDate, scope.filters.period, scope.anchor) || row.installmentPlan && outstanding(row, scope.anchor) > 0))} /></>;
  }
  const historic = series.map(point => {
    const month = new Date(`${point.date}T00:00:00Z`); const cutoff = new Date(Date.UTC(month.getUTCFullYear(), month.getUTCMonth() + 1, 0)).toISOString().slice(0, 10);
    const invoices = scope.invoices.filter(row => row.dueDate <= cutoff && registered.has(row.companyId));
    const universe = new Set(invoices.map(row => row.companyId)); const debtors = new Set(invoices.filter(row => row.dueDate < cutoff && outstanding(row, cutoff) > 0).map(row => row.companyId));
    return { universe: universe.size, rate: universe.size ? (universe.size - debtors.size) / universe.size * 100 : 0 };
  });
  const greRows = dataset.gres.filter(gre => [...representativeGre.values()].includes(gre.id)); const states = ['Adimplente', 'Com saldo vencido', 'Fora do universo financeiro'];
  const matrix: [number, number, number][] = greRows.flatMap((gre, y) => states.map((state, x) => [x, y, scope.companies.filter(company => representativeGre.get(company.id) === gre.id && (state === states[0] ? eligibleIds.has(company.id) && !lateIds.has(company.id) : state === states[1] ? lateIds.has(company.id) : !eligibleIds.has(company.id))).length] as [number, number, number]));
  return <><Notice>Adimplência é calculada por empresa, reunindo obrigações de seus registros. O denominador inclui empresas localizadas com obrigação vencida até a competência. Empresas externas e sem obrigação elegível ficam fora da taxa.</Notice><SmallStats onInfo={onInfo} rows={[["Universo financeiro", num(m.financeUniverse), 'financeUniverse'], ['Empresas adimplentes', num(m.compliantCompanies), 'compliantCompanies'], ['Empresas com saldo vencido', num(m.delinquentCompanies), 'delinquentCompanies'], ['Fora do denominador', num(scope.companies.length - m.financeUniverse)]]} /><div className="p-grid two"><Panel title="Situação financeira e denominador ao longo do tempo" subtitle="Percentual por empresa e quantidade de empresas elegíveis em cada fechamento." info="compliance" onInfo={onInfo} actions={<Toggle value={rateMeasure} set={setRateMeasure} label="Taxa financeira" choices={[["compliance", "Adimplência"], ["delinquency", "Inadimplência"]]} />}><Chart option={comboOption(series.map(row => row.label), historic.map(row => row.universe), historic.map(row => Number((row.universe ? rateMeasure === 'compliance' ? row.rate : 100 - row.rate : 0).toFixed(2))), 'Empresas elegíveis', rateMeasure === 'compliance' ? 'Adimplência (%)' : 'Inadimplência (%)')} height={360} ariaLabel="Taxa mensal de adimplência e seu denominador" summary="Taxa zero em universo vazio não representa adimplência universal. Todos os pagamentos respeitam sua data efetiva." /></Panel><Panel title="GRE × situação financeira da empresa" subtitle="Atribuição única por empresa; matriz no recorte ou primeiro estabelecimento visível."><Chart option={heatmapOption(states, greRows.map(row => row.name), matrix)} height={360} ariaLabel="Situação financeira das empresas por GRE" onPick={params => { const [x, y] = params.value; const gre = greRows[y]; if (!gre) return; onSubset(scope.companies.filter(company => representativeGre.get(company.id) === gre.id && (x === 0 ? eligibleIds.has(company.id) && !lateIds.has(company.id) : x === 1 ? lateIds.has(company.id) : !eligibleIds.has(company.id))).map(row => row.id), `${gre.name} · ${states[x]}`, 'Situação por empresa segundo obrigações e pagamentos até a competência.'); }} /></Panel></div></>;
}

function EmploymentPanels(props: DomainPanelsProps) {
  const { scope, view, onCity, onCnae, onCbo, onInfo } = props;
  const [territoryMode, setTerritoryMode] = useState('map');
  const technicalCodes = dataset.cbos.filter(row => row.technical).map(row => row.code);
  const selectedCodes = scope.filters.cboCodes;
  const occupation = selectedCodes.length === 1 ? selectedCodes[0] : '';
  const technicalOnly = selectedCodes.length === technicalCodes.length && technicalCodes.every(code => selectedCodes.includes(code)) ? 'technical' : 'all';
  const facts = scope.employment;
  const months = [...new Set(facts.map(row => row.month))].sort(); const firstMonth = months[0]; const lastMonth = months.at(-1);
  const latest = facts.filter(row => row.month === lastMonth);
  const cityIds = [...new Set(facts.map(row => row.cityId))];
  const growthByCity = cityIds.map(id => { const cityFacts = facts.filter(row => row.cityId === id); const initial = total(cityFacts.filter(row => row.month === firstMonth), row => row.stock - row.admissions + row.dismissals); const current = total(cityFacts.filter(row => row.month === lastMonth), row => row.stock); return { id, label: cityById.get(id)?.name ?? id, start: initial, stock: current, balance: current - initial, rate: initial ? (current - initial) / initial * 100 : 0 }; });
  const employmentWarning = scope.employmentScopeLimited ? <Notice><strong>O recorte empresarial não identifica trabalhadores.</strong> Seleção de empresas, CNPJ, porte ou situação cadastral não é aplicada a esta fonte. Os dados de emprego seguem apenas território, CNAE, CBO e período; não são atribuídos a uma empresa ou profissional.</Notice> : <Notice>Fonte de emprego demonstrativa agregada por município × CNAE × CBO × mês. Ocupação declarada não comprova formação ou registro; admissões e desligamentos são fluxos.</Notice>;
  const controls = <><Toggle value={technicalOnly} set={value => onCbo(value === 'technical' ? technicalCodes : [])} label="Universo de ocupações" choices={[["all", 'Todas'], ['technical', 'Técnicas']]} /><select aria-label="Selecionar ocupação CBO" value={occupation} onChange={event => onCbo(event.target.value ? [event.target.value] : [])}><option value="">{selectedCodes.length > 1 ? `${selectedCodes.length} CBOs selecionadas` : 'Todas as CBOs'}</option>{dataset.cbos.map(row => <option key={row.code} value={row.code}>{row.label}</option>)}</select></>;
  const flows = { admissions: total(facts, row => row.admissions), dismissals: total(facts, row => row.dismissals) };
  const employmentStats = <SmallStats onInfo={onInfo} rows={[["Estoque do recorte de ocupações", num(total(latest, row => row.stock)), 'employees'], ['Admissões no período', num(flows.admissions), 'admissions'], ['Desligamentos no período', num(flows.dismissals), 'dismissals'], ['Saldo do período', num(flows.admissions - flows.dismissals), 'employmentBalance']]} />;
  if (!facts.length) return <>{employmentWarning}<Panel title="Recorte de ocupações" subtitle="Os controles atualizam indicadores e análises agregadas de emprego." actions={controls}><div className="p-empty"><strong>Sem fatos de emprego neste recorte</strong><p>Altere território, CNAE, ocupação ou período para consultar a amostra.</p></div></Panel></>;

  if (view === 'ocupacoes') {
    const cnaeCodes = [...new Set(latest.map(row => row.cnae))].sort(); const cboCodes = dataset.cbos.filter(row => latest.some(fact => fact.cbo === row.code));
    const matrix: [number, number, number][] = cnaeCodes.flatMap((code, y) => cboCodes.map((cbo, x) => [x, y, total(latest.filter(row => row.cnae === code && row.cbo === cbo.code), row => row.stock)] as [number, number, number]));
    const cboTotals = cboCodes.map(row => ({ ...row, value: total(latest.filter(fact => fact.cbo === row.code), fact => fact.stock) }));
    return <>{employmentWarning}<div className="p-grid two"><Panel title="CNAE × CBO: estoque de empregos" subtitle={`Competência ${lastMonth ?? 'sem dados'}; clique em uma célula para selecionar o CNAE e a ocupação.`} actions={controls} info="employees" onInfo={onInfo}><Chart option={heatmapOption(cboCodes.map(row => row.label), cnaeCodes, matrix)} height={440} ariaLabel="Estoque agregado por CNAE e CBO" onPick={params => { const [x, y] = params.value; onCbo(cboCodes[x]?.code ? [cboCodes[x].code] : []); if (cnaeCodes[y]) onCnae(cnaeCodes[y]); }} /></Panel><Panel title="Distribuição das ocupações" subtitle="Cada vínculo formal aparece em uma ocupação, incluindo as demais atividades." info="technicalEmployees" onInfo={onInfo}><Chart option={barOption(cboTotals.map(row => ({ label: row.label, value: row.value })), 'Vínculos formais agregados')} height={440} ariaLabel="Distribuição agregada das ocupações CBO" onPick={params => { const code = cboTotals[params.dataIndex]?.code; if (code) onCbo([code]); }} summary="As CBOs técnicas são uma taxonomia demonstrativa. Não existe relacionamento com as pessoas do cadastro profissional." /></Panel></div></>;
  }
  if (view === 'territorio') {
    const compatibleEstablishments = dataset.establishments.filter(row => cityIds.includes(row.cityId) && (!scope.filters.cnaeCodes.length || scope.filters.cnaeCodes.includes(row.cnaeMain)));
    const compatibleEstablishmentIds = new Set(compatibleEstablishments.map(row => row.id));
    const registrationIds = new Set(dataset.registrations.filter(row => compatibleEstablishmentIds.has(row.establishmentId)).map(row => row.id));
    const startDate = `${firstMonth}-01`; const finalDate = scope.anchor; const registrationCity = new Map(dataset.registrations.map(row => [row.id, establishmentById.get(row.establishmentId)?.cityId]));
    const statesAt = (cutoff: string) => { const states = new Map<string, boolean>(); for (const movement of [...dataset.movements].sort((a, b) => a.date.localeCompare(b.date))) if (registrationIds.has(movement.registrationId) && movement.date <= cutoff) states.set(movement.registrationId, movement.type === 'Novo registro' || movement.type === 'Reativação'); return states; };
    const initialCutoff = new Date(Date.parse(`${startDate}T00:00:00Z`) - 86400000).toISOString().slice(0, 10); const initial = statesAt(initialCutoff); const current = statesAt(finalDate);
    const comparisons = growthByCity.map(row => { const before = [...initial].filter(([id, active]) => active && registrationCity.get(id) === row.id).length; const after = [...current].filter(([id, active]) => active && registrationCity.get(id) === row.id).length; return { ...row, registryGrowth: before ? (after - before) / before * 100 : 0 }; });
    const greGrowth = bucketCounts(growthByCity, row => greById.get(cityById.get(row.id)?.greId ?? '')?.name ?? 'Não identificada', row => row.balance);
    const mapGroups: Group[] = growthByCity.map(row => ({ id: row.id, label: row.label, companies: 0, establishments: 0, registered: 0, notMatched: 0, coverage: 0, employment: row.stock, contracts: 0, overdue: 0, arts: 0, caos: 0 }));
    return <>{employmentWarning}<div className="p-grid two"><Panel title="Crescimento do emprego e dos registros" subtitle="Mesmo território, CNAE principal e período; filtros empresariais são excluídos da comparação." actions={controls}><Chart option={scatterOption(comparisons.map(row => ({ label: row.label, x: Number(row.rate.toFixed(1)), y: Number(row.registryGrowth.toFixed(1)), size: row.stock / 100 })), 'Emprego: crescimento (%)', 'Registros ativos: crescimento (%)')} height={390} ariaLabel="Crescimento do emprego formal e dos registros ativos por município" onPick={params => { const row = comparisons[params.dataIndex]; if (row) onCity(row.id); }} summary="Variação do estoque de emprego comparada à variação do estoque de registros ativos, com bases iniciais próprias. Crescimento não constitui sinal automático de irregularidade." /></Panel><Panel title={territoryMode === 'map' ? 'Mapa do emprego por município' : 'Saldo de empregos por GRE'} subtitle={territoryMode === 'map' ? `Estoque ${lastMonth}, segundo o recorte global de CBO. Selecione um município sem atribuir os fatos a CNPJs.` : 'Soma dos municípios demonstrativos; vínculo territorial precisa de validação institucional.'} actions={<Toggle value={territoryMode} set={setTerritoryMode} label="Visualização territorial de emprego" choices={[["map", 'Mapa'], ['gre', 'Comparar GREs']]} />}>{territoryMode === 'map' ? <MunicipalMap groups={mapGroups} metric="employment" onCity={onCity} /> : <Chart option={barOption(greGrowth, 'Saldo de empregos')} height={390} ariaLabel="Saldo de empregos formais por GRE" summary="As GREs são as unidades documentadas no organograma. A cobertura municipal desta amostra é demonstrativa." />}</Panel></div><Records title="Comparação territorial agregada" subtitle="Dados agregados, sem coluna de empresa ou CNPJ. Selecione um município para aprofundar." headers={['Município', 'Estoque inicial', 'Estoque final', 'Saldo', 'Emprego: variação', 'Registros: variação']} initialSort="rank" rows={comparisons.map(row => ({ id: row.id, rank: row.balance, search: row.label, cells: [<button className="p-company-link" onClick={() => onCity(row.id)}>{row.label}</button>, num(row.start), num(row.stock), num(row.balance), pct(row.rate), pct(row.registryGrowth)] }))} /></>;
  }
  const ranked = [...growthByCity].sort((a, b) => b.rate - a.rate); const stocks = months.map(month => total(facts.filter(row => row.month === month), row => row.stock));
  return <>{employmentWarning}<div className="p-grid two"><Panel title="Fluxos e estoque de emprego formal" subtitle="As duas escalas separam movimentos mensais do estoque ao fim de cada competência." info="employmentBalance" onInfo={onInfo} actions={controls}><Chart option={lineOption(months, [{ name: 'Admissões', values: months.map(month => total(facts.filter(row => row.month === month), row => row.admissions)), type: 'bar' }, { name: 'Desligamentos', values: months.map(month => total(facts.filter(row => row.month === month), row => row.dismissals)), type: 'bar' }, { name: 'Estoque', values: stocks, axis: 1 }], ['Movimentos', 'Estoque'])} height={360} ariaLabel="Admissões, desligamentos e estoque agregado de empregos formais" summary={`Último estoque: ${num(total(latest, row => row.stock))} vínculos formais. Admissões menos desligamentos conciliam a variação do estoque.`} /></Panel><Panel title="Municípios com maior crescimento" subtitle="Variação sobre o estoque no início do período; todas as ocupações ou recorte técnico escolhido."><Chart option={barOption(ranked.slice(0, 10).map(row => ({ label: row.label, value: Number(row.rate.toFixed(1)) })), 'Crescimento (%)')} height={360} ariaLabel="Ranking do crescimento agregado do emprego por município" onPick={params => { const row = ranked[params.dataIndex]; if (row) onCity(row.id); }} /></Panel></div></>;
}

function ContractPanels(props: DomainPanelsProps) {
  const { scope, view, onSubset, onCompany, onCnae, onCity } = props;
  const [dimension, setDimension] = useState('category');
  const buyerById = new Map(dataset.buyers.map(row => [row.id, row]));
  const series = useMemo(() => makeSeries(scope), [scope]);
  const key = (row: Scope['contracts'][number]) => dimension === 'city' ? establishmentById.get(row.establishmentId)?.cityId ?? '' : dimension === 'cnae' ? establishmentById.get(row.establishmentId)?.cnaeMain ?? '' : row.category;
  const label = (id: string) => dimension === 'city' ? cityById.get(id)?.name ?? id : id;
  const values = bucketCounts(scope.contracts, key, row => row.value);
  const suppliers = bucketCounts(scope.contracts, row => row.companyId, row => row.value);
  const composition = { tooltip: { formatter: (p: any) => `${p.name}<br/>${money(p.value)}` }, series: [{ type: 'treemap', roam: false, nodeClick: false, breadcrumb: { show: false }, label: { fontSize: 13 }, itemStyle: { borderColor: '#fff', borderWidth: 3 }, data: values.map((row, i) => ({ name: label(row.label), id: row.label, value: row.value, itemStyle: { color: chartColors[i % chartColors.length] } })) }] };
  const supplierShare = suppliers.slice(0, 10).map((row, i) => ({ label: `#${i + 1} · ${companyName(row.label)}`, value: row.value }));
  const tableRows: RecordRow[] = scope.contracts.map(row => ({ id: row.id, date: row.date, rank: row.value, status: row.category, search: `${row.id} ${companyName(row.companyId)} ${row.object} ${buyerById.get(row.buyerId)?.name}`, cells: [<>{companyButton(row.companyId, onCompany)}<small>{row.id} · {date(row.date)}</small></>, <>{row.object}<small>{buyerById.get(row.buyerId)?.name}</small></>, row.category, money(row.value)] }));
  return <><div className="p-grid two"><Panel title={view === 'fornecedores' ? 'Concentração dos fornecedores' : 'Valor contratado ao longo do período'} subtitle={view === 'fornecedores' ? 'Dez maiores fornecedores; cada contrato entra uma vez no valor.' : 'Data publicada · valor contratado não é faturamento nem execução.'}><Chart option={view === 'fornecedores' ? barOption(supplierShare, 'Valor contratado (R$)') : lineOption(series.map(row => row.label), [{ name: 'Valor contratado (R$)', values: series.map(row => row.contractValue), type: 'bar' }], ['R$'])} height={340} ariaLabel={view === 'fornecedores' ? 'Concentração do valor contratado nos fornecedores' : 'Evolução mensal do valor dos contratos públicos'} onPick={params => { if (view === 'fornecedores') { const row = suppliers[params.dataIndex]; if (row) onSubset([row.label], companyName(row.label), 'Fornecedor selecionado pelo valor agregado dos contratos.'); } else { const point = series[params.dataIndex]; if (point) onSubset(companyIds(scope.contracts.filter(row => row.date.startsWith(point.date.slice(0, 7)))), `Contratos · ${point.label}`, 'Fornecedores com contratos publicados no mês.'); } }} /></Panel><Panel title="Composição das contratações" subtitle="Área proporcional ao valor · categoria publicada, CNAE ou município do fornecedor." actions={<Toggle value={dimension} set={setDimension} label="Distribuição das contratações" choices={[["category", 'Objeto'], ['cnae', 'CNAE'], ['city', 'Município']]} />}><Chart option={composition} height={340} ariaLabel="Treemap do valor das contratações por categoria, CNAE ou município" onPick={params => { const id = params.data?.id; if (!id) return; if (dimension === 'city') onCity(id); else if (dimension === 'cnae') onCnae(id); else onSubset(companyIds(scope.contracts.filter(row => row.category === id)), id, 'Fornecedores da categoria de objeto publicada.'); }} /></Panel></div><p className="p-source">PNCP demonstrativo · panorama econômico. Classificação explicável, revisão de documentos e sinais de verificação estão em Fiscalização.</p><Records title="Contratações públicas do recorte" subtitle="Busca por fornecedor, objeto ou órgão contratante; categoria publicada na origem." headers={['Fornecedor / contrato', 'Objeto / órgão', 'Categoria publicada', 'Valor contratado']} rows={tableRows} /></>;
}

export default function DomainPanels(props: DomainPanelsProps) {
  if (props.page === 'financial' && !props.financialAllowed) return <div className="p-empty"><ShieldCheck size={28} /><strong>Acesso financeiro restrito</strong><p>Este perfil permite consultar cadastro e indicadores públicos. Os valores e as obrigações financeiras exigem um perfil autorizado.</p></div>;
  if (!props.scope.companies.length && props.page !== 'employment') return <div className="p-empty"><Search size={26} /><strong>Nenhum registro neste recorte</strong><p>Ajuste os filtros ou remova a seleção cruzada para continuar a análise.</p></div>;
  switch (props.page) {
    case 'registry': return <RegistryPanels {...props} />;
    case 'inspection': return <InspectionPanels {...props} />;
    case 'technical': return <TechnicalPanels {...props} />;
    case 'cao': return <CaoPanels {...props} />;
    case 'financial': return <FinancialPanels {...props} />;
    case 'employment': return <EmploymentPanels {...props} />;
    case 'contracts': return <ContractPanels {...props} />;
    default: return null;
  }
}
